type FacilitiesView = "home" | "requests" | "new-request" | "keys" | "spaces" | "events" | "alerts" | "warehouse" | "supplies" | "directory" | "account" | "reports" | "floor-plans" | "customize";
const stateKey = "navigate.facilities-demo.state.v3";
const navItems: Array<{ key: FacilitiesView; label: string; adminOnly?: boolean; operatorOnly?: boolean }> = [
  { key: "home", label: "Home" },
  { key: "requests", label: "Work requests" },
  { key: "keys", label: "Keys & access" },
  { key: "spaces", label: "Reserve space" },
  { key: "events", label: "Event records", operatorOnly: true },
  { key: "alerts", label: "Notifications", operatorOnly: true },
  { key: "supplies", label: "Office supplies" },
  { key: "warehouse", label: "Warehouse" },
  { key: "directory", label: "Directory" },
  { key: "account", label: "Access & profile" },
  { key: "reports", label: "Reports", adminOnly: true },
  { key: "floor-plans", label: "Floor plans", adminOnly: true },
];

function loadState() {
  if (typeof window === "undefined") return cloneFacilitiesDemoState();
  try {
    const stored = window.localStorage.getItem(stateKey);
    return stored ? { ...cloneFacilitiesDemoState(), ...JSON.parse(stored) } as FacilitiesDemoState : cloneFacilitiesDemoState();
  } catch { return cloneFacilitiesDemoState(); }
}

function formatStatus(status: string) { return status.replaceAll("_", " "); }
function statusClass(status: string) { return status === "complete" || status === "approved" ? "confirmed" : status === "urgent" || status === "declined" ? "declined" : "pending"; }
function nextId(prefix: string, existing: Array<{ id: string }>, fallback: number) {
  return Math.max(fallback, ...existing.map((item) => Number(item.id.replace(/\D/g, "")) || 0)) + 1;
}

type FacilitiesCampus = "All campuses" | "Summerlin Campus" | "Henderson Campus" | "South Jordan Campus";
const departmentOptions = ["Student Affairs", "College of Medicine", "Academic Affairs", "Admissions", "University Advancement", "Facilities"];
const staffOptions = ["Alex Rivera", "Jordan Kim", "Nina Foster", "Leo Martinez", "Sam Patel"];
function requestCampus(request: FacilitiesRequest, rooms: FacilitiesDemoState["rooms"]) {
  return rooms.find((room) => request.location.includes(room.name))?.building || (request.location.toLowerCase().includes("south jordan") ? "South Jordan Campus" : request.location.toLowerCase().includes("henderson") ? "Henderson Campus" : "Summerlin Campus");
}
function reservationCampus(reservation: FacilitiesReservation) { return reservation.campus || (reservation.roomId.startsWith("room-sj") ? "South Jordan Campus" : reservation.roomId.startsWith("room-h") ? "Henderson Campus" : "Summerlin Campus"); }

