  return <div className="facilities-page" data-tutorial-id="facilities-staff-home">
    <div className="facilities-page-heading"><div><p className="kicker">Facilities staff</p><h1>Today’s field work.</h1><p>Start with urgent notifications, complete-by dates, and the work assigned to you.</p></div><div><button className="secondary-button" onClick={() => onNavigate("alerts")}>Notifications</button><button className="primary-button" onClick={() => onNavigate("requests")}>Open work queue</button></div></div>
    <div className="facilities-metrics"><article><span>Assigned to me</span><strong>{assigned.length}</strong><small>open work orders</small></article><article><span>Urgent</span><strong>{urgent.length}</strong><small>campus-wide alerts</small></article><article><span>Prep today</span><strong>{state.requests.filter((item) => item.status === "prep").length}</strong><small>events and work</small></article><article><span>Counts due</span><strong>{state.stock.filter((item) => item.onHand <= item.reorderPoint).length}</strong><small>inventory checks</small></article></div>
    <section className="facilities-panel"><header><div><p className="kicker">My agenda</p><h2>Assigned work</h2></div><button className="text-button" onClick={() => onNavigate("requests")}>See all work</button></header><div className="facilities-request-list">{assigned.length ? assigned.map((item) => <button key={item.id} onClick={() => onOpen(item)}><span className={`facilities-request-icon facilities-request-icon--${item.category}`}><FacilitiesIcon name="requests" /></span><span><small>{item.id} · {item.location}</small><strong>{item.title}</strong><em>Complete by {new Date(`${item.requestedFor}T12:00:00`).toLocaleDateString()}</em></span><span className={`status-chip status-chip--${statusClass(item.priority)}`}>{item.priority}</span></button>) : <p>No work is currently assigned to you.</p>}</div></section>
    <div className="facilities-two-column"><section className="facilities-panel"><header><div><p className="kicker">Urgency</p><h2>Work-order notifications</h2></div><span>{urgent.length} active</span></header><div className="facilities-mini-list">{urgent.map((item) => <button key={item.id} onClick={() => onOpen(item)}><span><strong>{item.title}</strong><em>{item.location} · due {item.requestedFor}</em></span><span className="status-chip status-chip--declined">Urgent</span></button>)}</div></section><UsagePanel state={state} /></div>
  </div>;
